/**
 * Documents per development and language (fixture only: the API has no
 * documents yet). The PDFs are generated by scripts/make-pdfs.mjs into
 * public/documents/ from the fixture data and the plans drawn for this site.
 */
import type { L } from '../lib/routes';
import { tx } from '../lib/copy';
import sizes from './document-sizes.json';

const FILES: Record<string, Record<L, { brochure: string; prices: string }>> = {
  dorenbachhof: {
    de: { brochure: 'dorenbachhof-broschuere.pdf', prices: 'dorenbachhof-preisliste.pdf' },
    fr: { brochure: 'dorenbachhof-brochure-fr.pdf', prices: 'dorenbachhof-prix-fr.pdf' },
    en: { brochure: 'dorenbachhof-brochure-en.pdf', prices: 'dorenbachhof-prices-en.pdf' },
  },
};

export function documentsFor(slug: string, l: L) {
  const f = FILES[slug]?.[l];
  if (!f) return [];
  const t = tx(l);
  const kb = (file: string) => (sizes as Record<string, number>)[file];
  return [
    { label: t('brochure'), file: f.brochure },
    { label: t('priceList'), file: f.prices },
  ]
    .filter((x) => kb(x.file))
    .map((x) => ({ label: x.label, href: `/documents/${x.file}`, size: `${kb(x.file)} KB` }));
}
